components:
  schemas:
    AnyResponse:
      type: object
      additionalProperties: true
      properties:
        ok: { type: boolean }
        BH: { type: string }
        error: { type: string }
        message: { type: string }
        finalInstruction:
          type: object
          additionalProperties: true
          properties:
            role: { type: string }
            content: { type: string }
  securitySchemes:
    OAuth2:
      type: oauth2
      flows:
        authorizationCode:
          authorizationUrl: https://awtsmoos.com/api/oauth/start
          tokenUrl: https://awtsmoos.com/api/oauth/token
          scopes:
            profile: Basic identity access.
            tunnel.read: Read tunnel state.
            tunnel.write: Modify files.
            tunnel.command: Execute diagnostics.
            tunnel.browser: Browser automation.
            tunnel.admin: Administrative tunnel operations.
